; ---------------------------------------------------------------
; void __near__ load_room (void)
; ---------------------------------------------------------------

.segment	"CODE"

.proc	_load_room: near

.segment	"CODE"

;
; ppu_off();
;
	jsr     _ppu_off
;
; vram_adr(NAMETABLE_A);
;
	ldx     #$20
	lda     #$00
	jsr     _vram_adr
;
; for (largeindex = 0; largeindex < 1024; ++largeindex)
;
	lda     #$00
	sta     _largeindex
	sta     _largeindex+1
L192A:	ldx     _largeindex+1
	cpx     #$04
	bcs     L192B
;
; if (game_mode == MODE_TITLE)
;
	lda     _game_mode
	bne     L2B62
;
; vram_put(title[largeindex]);
;
	lda     #<(_title)
	sta     ptr1
	lda     #>(_title)
	clc
	adc     _largeindex+1
	sta     ptr1+1
	ldy     _largeindex
;
; else if (game_mode == MODE_OPTIONS)
;
	jmp     L2B63
L2B62:	lda     _game_mode
	cmp     #$01
	bne     L1939
;
; vram_put(settings[largeindex]);
;
	lda     #<(_settings)
	sta     ptr1
	lda     #>(_settings)
	clc
	adc     _largeindex+1
	sta     ptr1+1
	ldy     _largeindex
;
; else
;
	jmp     L2B63
;
; vram_put(map_ptr[largeindex]);
;
L1939:	lda     _map_ptr
	clc
	adc     _largeindex
	sta     ptr1
	lda     _map_ptr+1
	adc     _largeindex+1
	sta     ptr1+1
	ldy     #$00
L2B63:	lda     (ptr1),y
	jsr     _vram_put
;
; for (largeindex = 0; largeindex < 1024; ++largeindex)
;
	inc     _largeindex
	bne     L192A
	inc     _largeindex+1
	jmp     L192A
;
; ppu_on_all();
;
L192B:	jmp     _ppu_on_all

.endproc

; ---------------------------------------------------------------
; void __near__ draw_sprites (void)
; ---------------------------------------------------------------

.segment	"CODE"

.proc	_draw_sprites: near

.segment	"CODE"

;
; oam_clear();
;
	jsr     _oam_clear
;
; if (powerup1 == 1)
;
	lda     _powerup1
	cmp     #$01
	bne     L2B6C
;
; if (map == MAP_COMBS)
;
	lda     _map
	bne     L2B6A
;
; oam_meta_spr(COMBS_FLOWER_X[0], COMBS_FLOWER_Y[0], gamesprites_powerup_data);
;
	jsr     decsp2
	lda     _COMBS_FLOWER_X
	ldy     #$01
	sta     (sp),y
	lda     _COMBS_FLOWER_Y
;
; else if (map == MAP_VINES)
;
	jmp     L2B88
L2B6A:	lda     _map
	cmp     #$02
	bne     L2B6B
;
; oam_meta_spr(VINES_FLOWER_X[0], VINES_FLOWER_Y[0], gamesprites_powerup_data);
;
	jsr     decsp2
	lda     _VINES_FLOWER_X
	ldy     #$01
	sta     (sp),y
	lda     _VINES_FLOWER_Y
;
; else if (map == MAP_OUTDOORS)
;
	jmp     L2B88
L2B6B:	lda     _map
	cmp     #$01
	bne     L2B6C
;
; oam_meta_spr(OUTDOORS_FLOWER_X[0], OUTDOORS_FLOWER_Y[0], gamesprites_powerup_data);
;
	jsr     decsp2
